macro.sample.deck:
var n = deck.AddSlide();
deck.SetTitle(n, "Summary");
deck.SetBody(n, "Slides: " + deck.SlideCount);
app.Log(deck.Title(n));

macro.sample.folio:
var n = doc.AppendParagraph("Summary");
doc.SetStyle(n, "Heading 1");
doc.AppendParagraph("Words: " + doc.WordCount);
app.Log(doc.Paragraph(n));
